package org.jsoup.safety;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.mockito.Mockito;

import static org.junit.Assert.*;
import static org.mockito.Mockito.when;

@RunWith(JUnit4.class)
public class SafelistTest {

    @Test
    public void none_SafelistReturnsNone() {
        Safelist safelist = Safelist.none();
        assertNotNull(safelist);
        assertEquals(Safelist.NONE, safelist.toString());
    }

    @Test
    public void simpleText_SafelistContainsSimpleTextTags() {
        Safelist safelist = Safelist.simpleText();
        assertTrue(safelist.isSafeTag("img"));
        assertTrue(safelist.isSafeTag("br"));
        assertFalse(safelist.isSafeTag("script"));
    }

    @Test
    public void basic_SafelistContainsBasicTags() {
        Safelist safelist = Safelist.basic();
        assertTrue(safelist.isSafeTag("p"));
        assertTrue(safelist.isSafeTag("a"));
        assertFalse(safelist.isSafeTag("img"));
    }

    @Test
    public void basicWithImages_SafelistContainsBasicTagsAndImages() {
        Safelist safelist = Safelist.basicWithImages();
        assertTrue(safelist.isSafeTag("p"));
        assertTrue(safelist.isSafeTag("a"));
        assertTrue(safelist.isSafeTag("img"));
        assertFalse(safelist.isSafeTag("script"));
    }

    @Test
    public void relaxed_SafelistContainsRelaxedTags() {
        Safelist safelist = Safelist.relaxed();
        assertTrue(safelist.isSafeTag("p"));
        assertTrue(safelist.isSafeTag("a"));
        assertTrue(safelist.isSafeTag("img"));
        assertTrue(safelist.isSafeTag("script"));
    }

    @Test
    public void preserveRelativeLinks_PreserveLinks() {
        Safelist safelist = Safelist.relaxed();
        assertFalse(safelist.preserveRelativeLinks(false));
        assertTrue(safelist.preserveRelativeLinks(true));
    }

    @Test
    public void addTags_SafelistAddsTags() {
        Safelist safelist = Safelist.none();
        String[] tags = {"div", "span"};
        Safelist safelistWithTags = Safelist.addTags(tags);
        assertTrue(safelistWithTags.isSafeTag("div"));
        assertTrue(safelistWithTags.isSafeTag("span"));
    }

    @Test
    public void removeTags_SafelistRemovesTags() {
        Safelist safelist = Safelist.none();
        String[] tags = {"div", "span"};
        Safelist safelistWithTags = Safelist.addTags(tags);
        assertFalse(safelistWithTags.isSafeTag("div"));
        assertFalse(safelistWithTags.isSafeTag("span"));
    }

    @Test
    public void addAttributes_SafelistAddsAttributes() {
        Safelist safelist = Safelist.none();
        String tag = "img";
        String[] attributes = {"alt", "src"};
        Safelist safelistWithAttributes = Safelist.addAttributes(tag, attributes);
        assertEquals(2, ((Attributes) safelistWithAttributes.getEnforcedAttributes(tag)).size());
    }

    @Test
    public void removeAttributes_SafelistRemovesAttributes() {
        Safelist safelist = Safelist.none();
        String tag = "img";
        String[] attributes = {"alt", "src"};
        Safelist safelistWithAttributes = Safelist.addAttributes(tag, attributes);
        assertEquals(2, ((Attributes) safelistWithAttributes.getEnforcedAttributes(tag)).size());
        Safelist safelistWithoutAttributes = Safelist.removeAttributes(tag, attributes);
        assertEquals(0, ((Attributes) safelistWithoutAttributes.getEnforcedAttributes(tag)).size());
    }

    @Test
    public void addEnforcedAttribute_SafelistAddsEnforcedAttributes() {
        Safelist safelist = Safelist.none();
        String tag = "img";
        String attribute = "alt";
        String value = "image.jpg";
        Safelist safelistWithEnforcedAttribute = Safelist.addEnforcedAttribute(tag, attribute, value);
        assertEquals(1, ((Attributes) safelistWithEnforcedAttribute.getEnforcedAttributes(tag)).size());
    }

    @Test
    public void removeEnforcedAttribute_SafelistRemovesEnforcedAttributes() {
        Safelist safelist = Safelist.none();
        String tag = "img";
        String attribute = "alt";
        Safelist safelistWithEnforcedAttribute = Safelist.addEnforcedAttribute(tag, attribute, "image.jpg");
        assertEquals(1, ((Attributes) safelistWithEnforcedAttribute.getEnforcedAttributes(tag)).size());
        Safelist safelistWithoutEnforcedAttribute = Safelist.removeEnforcedAttribute(tag, attribute);
        assertEquals(0, ((Attributes) safelistWithoutEnforcedAttribute.getEnforcedAttributes(tag)).size());
    }

    @Test
    public void isSafeTag_ReturnsTrueForSafeTags() {
        Safelist safelist = Safelist.none();
        assertTrue(safelist.isSafeTag("img"));
        assertTrue(safelist.isSafeTag("br"));
        assertFalse(safelist.isSafeTag("script"));
    }

    @Test
    public void isSafeAttribute_ReturnsTrueForSafeAttributes() {
        Safelist safelist = Safelist.none();
        String tagName = "img";
        Element el = Mockito.mock(Element.class);
        Attribute attr = Mockito.mock(Attribute.class);
        when(el.getAttribute(0)).thenReturn("image.jpg");
        assertTrue(safelist.isSafeAttribute(tagName, el, attr));
    }

    @Test
    public void getEnforcedAttributes_ReturnsEnforcedAttributes() {
        Safelist safelist = Safelist.none();
        String tagName = "img";
        Attributes attributes = new Attributes(2);
        safelist.addAttributes(tagName, "alt", "src");
        assertEquals(2, ((Attributes) safelist.getEnforcedAttributes(tagName)).size());
    }
}
